    15	  createdAt: DateString,
    16	  updatedAt: DateString,
    17	});
    18	
    19	export const CreateBookingBody = Type.Object(
    20	  {
    21	    roomId: Type.String({ minLength: 1 }),
    22	    userId: Type.String({ minLength: 1 }),
    23	    title: Type.String({ minLength: 1, maxLength: 200 }),
    24	    startsAt: Type.String({ minLength: 1 }),
    25	    endsAt: Type.String({ minLength: 1 }),
    26	  },
    27	  { additionalProperties: false },
    28	);
