     1	export type ErrorCode =
     2	  | 'VALIDATION_ERROR'
     3	  | 'NOT_FOUND'
     4	  | 'ROOM_NAME_TAKEN'
     5	  | 'EMAIL_TAKEN'
     6	  | 'AMENITY_NAME_TAKEN'
     7	  | 'BOOKING_CONFLICT'
     8	  | 'INTERNAL_ERROR';
     9	
    10	export interface ErrorBody {
    11	  error: { code: ErrorCode; message: string; details: Record<string, unknown> };
    12	}
    13	
    14	export class AppError extends Error {
    15	  readonly code: ErrorCode;
    16	  readonly statusCode: number;
    17	  readonly details: Record<string, unknown>;
    18	
    19	  constructor(
    20	    code: ErrorCode,
    21	    statusCode: number,
    22	    message: string,
    23	    details: Record<string, unknown> = {},
    24	  ) {
    25	    super(message);
    26	    this.name = 'AppError';
    27	    this.code = code;
    28	    this.statusCode = statusCode;
    29	    this.details = details;
    30	  }
    31	}
    32	
    33	export function errorBody(
    34	  code: ErrorCode,
    35	  message: string,
    36	  details: Record<string, unknown> = {},
    37	): ErrorBody {
    38	  return { error: { code, message, details } };
    39	}
    40	
    41	export function validationFailed(message: string, details: Record<string, unknown> = {}): AppError {
    42	  return new AppError('VALIDATION_ERROR', 400, message, details);
    43	}
    44	
    45	export function notFound(what: string): AppError {
    46	  return new AppError('NOT_FOUND', 404, `${what} not found`);
    47	}
    48	
    49	export function roomNameTaken(name: string): AppError {
    50	  return new AppError('ROOM_NAME_TAKEN', 409, 'Room name is already in use', { name });
    51	}
    52	
    53	export function emailTaken(email: string): AppError {
    54	  return new AppError('EMAIL_TAKEN', 409, 'Email is already in use', { email });
    55	}
    56	
    57	export function bookingConflict(conflictingBookingId: string): AppError {
    58	  return new AppError('BOOKING_CONFLICT', 409, 'Room is already booked for this period', {
    59	    conflictingBookingId,
    60	  });
    61	}
