    12	export async function buildApp(options: BuildOptions = {}): Promise<FastifyInstance> {
    13	  const config = loadConfig();
    14	  const app = Fastify({
    15	    logger: options.logger === false ? false : { level: config.logLevel },
    16	  }).withTypeProvider<TypeBoxTypeProvider>();
    17	
    18	  // requestIdPlugin and errorHandlerPlugin are invoked directly on the root
    19	  // instance, not through app.register(). Fastify's register() creates an
    20	  // encapsulated child context, and hooks/handlers added inside it are not
    21	  // visible to sibling plugins (such as registerModules and the module
    22	  // plugins registered in later tasks). Calling them directly keeps the
    23	  // request-id header and the global error handler in effect for every
    24	  // route in the app.
    25	  await requestIdPlugin(app);
    26	  await errorHandlerPlugin(app);
    27	  await app.register(registerModules);
    28	
    29	  return app;
    30	}
