     1	import type { FastifyInstance } from 'fastify';
     2	import { AppError, errorBody } from '../shared/errors.js';
     3	
     4	export async function errorHandlerPlugin(app: FastifyInstance): Promise<void> {
     5	  app.setNotFoundHandler((_request, reply) => {
     6	    reply.code(404).send(errorBody('NOT_FOUND', 'Route not found'));
     7	  });
     8	
     9	  app.setErrorHandler((error, request, reply) => {
    10	    if (error instanceof AppError) {
    11	      reply.code(error.statusCode).send(errorBody(error.code, error.message, error.details));
    12	      return;
    13	    }
    14	
    15	    if (error.validation) {
    16	      reply
    17	        .code(400)
    18	        .send(errorBody('VALIDATION_ERROR', 'Request payload is invalid', {
    19	          issues: error.validation.map((issue) => issue.message ?? 'invalid'),
    20	        }));
    21	      return;
    22	    }
    23	
    24	    if (typeof error.statusCode === 'number' && error.statusCode >= 400 && error.statusCode < 500) {
    25	      reply.code(error.statusCode).send(errorBody('VALIDATION_ERROR', error.message));
    26	      return;
    27	    }
    28	
    29	    request.log.error({ err: error }, 'unhandled error');
    30	    reply.code(500).send(errorBody('INTERNAL_ERROR', 'Unexpected error'));
    31	  });
    32	}
