    51	export async function updateUser(id: string, input: UpdateUserInput): Promise<User> {
    52	  await getUser(id);
    53	  if (input.email !== undefined) {
    54	    assertValidEmail(input.email);
    55	    const existing = await repository.findByEmail(input.email);
    56	    if (existing && existing.id !== id) {
    57	      throw emailTaken(input.email);
    58	    }
    59	  }
    60	  if (input.name !== undefined) {
    61	    assertValidName(input.name);
    62	  }
    63	  return repository.update(id, input);
